#include <stdio.h> 
#include <math.h> 

const int CNT=32; 
int shr(int val, int n)   {  return val >> n; } 
int sign(int val) { return val >= 0 ? 1 : -1;  } 

int CORDIC(int* px, int* py, int n) { 
 int x, y, xi, yi, mul; 
 int ksi, i, xs, ys; 
 xi = *px; 
 yi = *py; 
 ksi = 1; 

loop: for (i=0; i<n; i++)  { 
  x = xi; 
  y = yi; 
  ksi = sign(y); 
  xi  = x + shr(y*ksi, i); 
  yi  = y - shr(x*ksi, i); 
 } 
 *px = x; 
 *py = y; 
 return x; 
} 

int main()  { 
 int x, y; 
 x = 3765479; 
 y = 4235609; 
 CORDIC(&x, &y, CNT); 
 printf("%d %d \n", x, y); 

 return 0; 
}

