Исходный код ядра OpenCL для реализации алгоритма CORDIC на 
Altera OpenCL SDK 
__kernel  
void CORDIC_try( // Input and output parameters 
                 __global const int *x, 
                 __global const int *y, 
                 __global int *restrict xo, 
                 __global int *restrict yo) 
{ 
    // Local storage 
    __local int X, X2; 
    __local int Y, Y2; 
    __local int sign;     

    X2 = *x; 
    Y2 = *y;  

    #pragma unroll 32 
    for (int i = 0; i < 32; i++) 
    {  
        X = X2; 
        Y = Y2; 
       sign = Y >= 0 ? 0 : 1; 

        X2 = X + (sign ? -Y : Y) >> i; 
        Y2 = Y - (sign ? -X : X) >> i; 
    } 

    *xo = X2; 
    *yo = Y2;     
}

